import {esc} from './text.js';
export const releasesURL='https://github.com/muneebwanee/BookWizOfficial/releases';
export function deviceCapabilities(host=globalThis.window?.BookWizHost){const native=!!host,platform=host?.platform||'web';return {native,platform,name:({ios:'iPhone & iPad',android:'Android',darwin:'macOS',win32:'Windows',linux:'Linux'})[platform]||'Web',widgets:native&&['ios','android'].includes(platform)&&typeof host.updateWidgets==='function',reminders:typeof host?.scheduleReminders==='function',apple:platform==='ios'&&typeof host?.generateText==='function',watch:platform==='ios'&&typeof host?.requestWatchNotes==='function',files:typeof host?.openBackup==='function',save:typeof host?.saveFile==='function',pdf:typeof host?.printHTML==='function',menus:['darwin','win32','linux'].includes(platform)&&typeof host?.openBackup==='function'};}
export const deviceFeatures=[
 {id:'widgets',title:'Home-screen widgets',detail:'Your book, daily goal, capture and writing time. Android also offers a clock, shortcuts and a weekly rhythm. Tap each widget to open its action.',where:'iPhone, iPad & Android',icon:'library',action:'widget-guide',button:'Choose widgets'},
 {id:'reminders',title:'Writing reminders',detail:'Choose your days and quiet hours. Reminders arrive even when BookWiz is closed.',where:'iPhone, iPad & Android',icon:'clock',action:'reminder-preferences',button:'Set reminders'},
 {id:'apple',title:'On-device writing',detail:'Apple Intelligence on compatible devices with iOS/iPadOS 26 or later, an enabled device model and a supported language.',where:'Compatible iPhone & iPad',icon:'cpu',action:'device-apple-model',button:'Set up on-device writing'},
 {id:'watch',title:'Watch notes',detail:'Capture an idea on a paired Apple Watch. Open your captures here; writing progress updates when your phone saves.',where:'iPhone & Apple Watch',icon:'note',action:'watch-captures',button:'Open captures'},
 {id:'files',title:'Files & backups',detail:'Open a BookWiz backup through your device’s file picker and save exports through system controls.',where:'Mobile & desktop apps',icon:'file',action:'import-backup',button:'Open a backup'},
 {id:'pdf',title:'Print & PDF',detail:'System printing on mobile, PDF saving on desktop and native sharing for your exports.',where:'Mobile & desktop apps',icon:'book',action:'device-print',button:'Open publishing'},
 {id:'menus',title:'Desktop shortcuts',detail:'File menus and keyboard shortcuts for starting a book, opening a backup, saving and printing.',where:'macOS, Windows & Linux',icon:'list',action:'shortcuts',button:'View shortcuts'}
];
const targets=[
 {id:'android',name:'Android',mark:'A',description:'Phones & tablets · Android 8 or later',url:releasesURL,label:'View Android downloads'},
 {id:'ios',name:'iPhone & iPad',mark:'iP',description:'With the paired Apple Watch companion',url:releasesURL,label:'View Apple release options'},
 {id:'win32',name:'Windows',mark:'W',description:'Windows desktop · x64 & ARM64',url:releasesURL,label:'View Windows downloads'},
 {id:'darwin',name:'macOS',mark:'M',description:'Apple silicon & Intel',url:releasesURL,label:'View Mac downloads'},
 {id:'linux',name:'Linux',mark:'L',description:'AppImage & Debian/Ubuntu packages',url:releasesURL,label:'View Linux downloads'},
 {id:'tvos',name:'Apple TV',mark:'TV',description:'Reading, read-aloud & outline board',url:releasesURL,label:'View TV release options'}
];
function deviceMark(id){const shape=id==='android'||id==='ios'?'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M10 18h4"/>':id==='tvos'?'<rect x="2" y="4" width="20" height="14" rx="2"/><path d="M8 22h8m-4-4v4"/>':'<rect x="4" y="3" width="16" height="13" rx="2"/><path d="m4 16-2 4h20l-2-4M9 20h6"/>';return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shape}</svg>`;}
function downloadList(c,I){return `<section id="app-downloads" class="app-downloads" aria-label="Platform downloads"><div class="app-download-list">${targets.map(t=>`<article class="app-download-row"><span class="device-mark">${deviceMark(t.id)}</span><div class="download-platform"><h2>${t.name}</h2><p>${t.description}</p></div><div class="download-action">${c.native&&c.platform===t.id?'<span class="download-installed">Installed</span>':`<a class="text-link" href="${releasesURL}" aria-label="${t.name} releases" target="_blank" rel="noopener">Releases ${I('external')}</a>`}</div></article>`).join('')}</div><p class="download-caption">Find app packages and release notes on GitHub Releases.</p></section>`;}
const unavailableReasons={widgets:'Home-screen widgets need the installed iPhone, iPad or Android app.',reminders:'Background reminders need a supported mobile installation.',apple:'Apple Intelligence requires a compatible iPhone or iPad with iOS/iPadOS 26 or later.',watch:'Watch captures need the paired iPhone app and Apple Watch companion.',files:'The native file picker is unavailable in this installation. Use Move your library below.',pdf:'Native printing is unavailable in this installation. Open Cover & publish for export options.',menus:'Native shortcuts are unavailable in this installation.'};
function featureList(features,c,I,B){return `<div class="device-feature-list" aria-label="Device features">${features.map(f=>`<article class="device-feature-row ${c.native&&!c[f.id]?'feature-unavailable':''}" id="feature-${f.id}"><span class="device-feature-icon">${I(f.icon)}</span><div class="device-feature-copy"><h3>${f.title}</h3><p>${f.detail}</p>${!c.native?`<span class="feature-platform">${f.where}</span>`:!c[f.id]?`<p class="feature-availability">${unavailableReasons[f.id]}</p>`:''}</div>${c.native?`<div class="device-feature-action">${c[f.id]?B(f.action,f.button,'arrow','secondary'):'<span class="badge neutral">Not supported here</span>'}</div>`:''}</article>`).join('')}</div>`;}

export function appsPage({I,B,version='1.0.0',bundledAndroid=false}){
 const c=deviceCapabilities(),mobile=['ios','android'].includes(c.platform),features=deviceFeatures.filter(f=>!c.native||(['widgets','reminders'].includes(f.id)?mobile:['apple','watch'].includes(f.id)?c.platform==='ios':f.id==='menus'?!mobile:true));
 const downloads=downloadList(c,I);
 return `<div class="page apps-page"><div class="page-intro"><div><h1>${c.native?'Device tools.':'Download BookWiz.'}</h1><p>${c.native?'Preferences and shortcuts for '+c.name+'.':'For your phone, tablet and desktop.'}</p></div>${c.native?`<span class="badge neutral">${c.name}</span>`:''}</div>
 ${c.native?featureList(features,c,I,B):downloads}
 ${!c.native?`<details class="device-availability"><summary>Features by device</summary><p class="device-availability-intro">Widgets, background reminders and on-device writing need an installed app. Books, the writing studio, 32 cover designs, connected AI and publishing stay available here.</p>${featureList(features,c,I,B)}</details>`:''}
 <details class="library-transfer"><summary>Move your library</summary><div class="transfer-content"><p>Books stay on the device where you write them. Export a backup, then open it in BookWiz on your other device. API keys and permissions stay private to each installation.</p><div class="row wrap gap8">${B('export-workspace','Back up my books','download','secondary')}${B('import-backup','Open a backup','upload','quiet')}</div></div></details>
 ${c.native?`<details class="app-other-devices"><summary>BookWiz for another device</summary>${downloads}</details>`:`<details class="web-install-option"><summary>Save a shortcut to the web studio</summary><div class="transfer-content"><p>Keep this web workspace on your home screen. Device tools are available in the installed apps.</p>${B('install-app','Add web shortcut','plus','quiet')}</div></details>`}
 <p class="download-privacy">${I('lock')} No account required. Your words stay yours.</p></div>`;
}
